<template><div class="page-hero"><div class="container"><p class="eyebrow">ORAL HEALTH GUIDE</p><h1>口腔健康科普</h1><p>同步重庆种博士口腔微信公众号专业内容，帮助您建立科学的口腔健康认知。</p></div></div><section class="section"><div class="container"><form class="article-search" @submit.prevent="search"><label for="article-keyword">搜索科普文章</label><div><input id="article-keyword" v-model="keyword" type="search" placeholder="输入牙齿、种植、正畸等关键词" /><button class="button button-primary" type="submit">搜索</button></div></form><div v-if="loading" class="state-card">正在加载科普内容…</div><div v-else-if="!result.list.length" class="state-card">暂未找到相关文章，请更换关键词。</div><div v-else class="article-grid article-list-grid"><RouterLink v-for="article in result.list" :key="article.id" :to="`/articles/${article.slug}`" class="article-card"><div class="article-cover"><img v-if="article.coverUrl" :src="article.coverUrl" :alt="article.title" loading="lazy" /><span v-else>ORAL<br>HEALTH</span></div><div class="article-body"><time>{{formatDate(article.publishedAt)}}</time><h2>{{article.title}}</h2><p>{{article.digest || '阅读专业口腔健康知识。'}}</p></div></RouterLink></div><div v-if="result.total>result.pageSize" class="pagination"><button :disabled="page<=1" @click="go(page-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="page*result.pageSize>=result.total" @click="go(page+1)">下一页</button></div></div></section></template>
<script setup lang="ts">import { onMounted,reactive,ref } from 'vue';import { RouterLink } from 'vue-router';import { Article,websiteApi } from '../api';import { formatDate } from '../site';const keyword=ref(''),page=ref(1),loading=ref(true);const result=reactive<{total:number;pageSize:number;list:Article[]}>({total:0,pageSize:12,list:[]});async function load(){loading.value=true;try{const data=await websiteApi.articles(page.value,keyword.value);Object.assign(result,data);}finally{loading.value=false;}}function search(){page.value=1;void load();}function go(value:number){page.value=value;void load();window.scrollTo({top:0,behavior:'smooth'});}onMounted(load);</script>
